import numpy as np


def _case(seed, B, N):
    r = np.random.default_rng(seed)
    return r.normal(size=(B, N)), r.normal(size=N), r.normal(size=(B, N))


def _cd_ok():
    x, g, d = _case(9, 3, 5)
    eps = 1e-5
    def f(x, g):
        xh = (x - x.mean(-1, keepdims=True)) / np.sqrt(x.var(-1, keepdims=True) + eps)
        return float((d * (xh * g)).sum())
    got = mi_layernorm_backward(x, g, d, eps)
    worst = 0.0
    for k, A in enumerate((x, g)):
        for i in np.ndindex(A.shape):
            P = [x.copy(), g.copy()]; M = [x.copy(), g.copy()]
            P[k][i] += 1e-6; M[k][i] -= 1e-6
            worst = max(worst, abs((f(*P) - f(*M)) / 2e-6 - got[k][i]))
    return worst < 1e-6
